===== src/types.ts =====
// Shared types for the Manhattan subway-accessibility application.

/** A single subway station parsed from the NYC Open Data CSV. */
export interface SubwayStation {
  name: string;
  routes: string;
  lon: number;
  lat: number;
}

/** GeoJSON-style polygon feature used for buildings, parks and water. */
export interface PolygonFeature {
  type: "Feature";
  geometry: {
    type: "Polygon";
    coordinates: number[][][]; // [ring][vertex][lon, lat]
  };
  properties: {
    id: number;
    kind: "building" | "park" | "water";
    name?: string;
    /** Extrusion height in metres (buildings only). */
    height?: number;
    /** Subway stations within 500 m of the footprint centroid (buildings only). */
    stationCount?: number;
  };
}

/** GeoJSON-style line feature used for roads. */
export interface LineFeature {
  type: "Feature";
  geometry: {
    type: "LineString";
    coordinates: number[][]; // [vertex][lon, lat]
  };
  properties: {
    id: number;
    kind: "road";
    highway?: string;
  };
}

export interface FeatureCollection<F> {
  type: "FeatureCollection";
  features: F[];
}

/** The four OSM base layers we fetch and render. */
export interface OsmLayers {
  buildings: FeatureCollection<PolygonFeature>;
  parks: FeatureCollection<PolygonFeature>;
  water: FeatureCollection<PolygonFeature>;
  roads: FeatureCollection<LineFeature>;
}
===== src/subway.ts =====
import type { SubwayStation } from "./types";

/**
 * Loads and parses the NYC Open Data subway-station CSV shipped in /public.
 * The file uses comma separation with quoted fields; we keep the station name,
 * its daytime routes and the GTFS latitude/longitude.
 */
export async function loadSubwayStations(
  url = "/subway_manhattan_clean.csv"
): Promise<SubwayStation[]> {
  console.log(`[subway] Loading subway stations from ${url} ...`);
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Failed to load subway CSV (HTTP ${res.status})`);
  }
  const text = await res.text();
  console.log(`[subway] CSV downloaded: ${(text.length / 1024).toFixed(1)} KB`);

  const rows = parseCsv(text);
  if (rows.length === 0) {
    throw new Error("Subway CSV is empty");
  }

  const header = rows[0];
  const idx = {
    name: header.indexOf("Stop Name"),
    routes: header.indexOf("Daytime Routes"),
    lat: header.indexOf("GTFS Latitude"),
    lon: header.indexOf("GTFS Longitude"),
  };
  if (idx.lat === -1 || idx.lon === -1) {
    throw new Error("Subway CSV is missing GTFS Latitude/Longitude columns");
  }

  const stations: SubwayStation[] = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const lat = Number(r[idx.lat]);
    const lon = Number(r[idx.lon]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    stations.push({
      name: idx.name >= 0 ? r[idx.name] : "Station",
      routes: idx.routes >= 0 ? r[idx.routes] : "",
      lat,
      lon,
    });
  }

  console.log(`[subway] Parsed ${stations.length} subway stations`);
  return stations;
}

/** Minimal RFC-4180-style CSV parser supporting quoted fields and CRLF. */
function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let field = "";
  let row: string[] = [];
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field);
      field = "";
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      row.push(field);
      field = "";
      if (row.length > 1 || row[0] !== "") rows.push(row);
      row = [];
    } else {
      field += c;
    }
  }
  if (field !== "" || row.length > 0) {
    row.push(field);
    if (row.length > 1 || row[0] !== "") rows.push(row);
  }
  return rows;
}
===== src/spatial.ts =====
import type { OsmLayers, SubwayStation } from "./types";

const RADIUS_M = 500;
const M_PER_DEG_LAT = 111_320;

/**
 * For every building, counts the subway stations whose distance to the
 * building footprint centroid is within RADIUS_M metres, and writes the result
 * onto `properties.stationCount`.
 *
 * Stations are bucketed into a ~500 m grid so each building only tests the
 * stations in its 9 neighbouring cells instead of all of them. Distances use
 * an equirectangular approximation, accurate to well under a metre at the 500 m
 * scale and Manhattan's latitude.
 */
export function countStationsPerBuilding(
  layers: OsmLayers,
  stations: SubwayStation[]
): { max: number; total: number } {
  console.log(
    `[spatial] Spatial join started: ${layers.buildings.features.length} buildings × ${stations.length} stations (r=${RADIUS_M} m)`
  );

  // Metres-per-degree-longitude at the mean station latitude, plus grid cells
  // sized to the search radius.
  const refLat = stations.length
    ? stations.reduce((s, st) => s + st.lat, 0) / stations.length
    : 40.78;
  const mPerDegLon = M_PER_DEG_LAT * Math.cos((refLat * Math.PI) / 180);
  const cellLat = RADIUS_M / M_PER_DEG_LAT;
  const cellLon = RADIUS_M / mPerDegLon;

  const grid = new Map<string, SubwayStation[]>();
  const key = (cx: number, cy: number) => `${cx}:${cy}`;
  for (const st of stations) {
    const cx = Math.floor(st.lon / cellLon);
    const cy = Math.floor(st.lat / cellLat);
    const k = key(cx, cy);
    const bucket = grid.get(k);
    if (bucket) bucket.push(st);
    else grid.set(k, [st]);
  }

  const r2 = RADIUS_M * RADIUS_M;
  let max = 0;
  let totalMatches = 0;
  let matchedBuildings = 0;

  for (const b of layers.buildings.features) {
    const [clon, clat] = centroid(b.geometry.coordinates[0]);
    const cx = Math.floor(clon / cellLon);
    const cy = Math.floor(clat / cellLat);

    let count = 0;
    for (let gx = cx - 1; gx <= cx + 1; gx++) {
      for (let gy = cy - 1; gy <= cy + 1; gy++) {
        const bucket = grid.get(key(gx, gy));
        if (!bucket) continue;
        for (const st of bucket) {
          const dx = (st.lon - clon) * mPerDegLon;
          const dy = (st.lat - clat) * M_PER_DEG_LAT;
          if (dx * dx + dy * dy <= r2) count++;
        }
      }
    }

    b.properties.stationCount = count;
    if (count > 0) {
      matchedBuildings++;
      totalMatches += count;
    }
    if (count > max) max = count;
  }

  console.log(
    `[spatial] Spatial join complete: ${matchedBuildings} buildings within 500 m of ≥1 station; max for a single building = ${max}`
  );
  return { max, total: totalMatches };
}

/** Average-vertex centroid of a closed ring (the duplicated closing vertex is ignored). */
function centroid(ring: number[][]): [number, number] {
  const n = ring.length > 1 ? ring.length - 1 : ring.length;
  let lon = 0;
  let lat = 0;
  for (let i = 0; i < n; i++) {
    lon += ring[i][0];
    lat += ring[i][1];
  }
  return [lon / n, lat / n];
}
